using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata — GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Type:       {personInfo.Type.Name}");
Console.WriteLine($"Kind:       {personInfo.Kind}");
Console.WriteLine($"Properties: {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

// Round-trip via the typed metadata to prove it works
var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");
var back = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: Name={back.Name}, Age={back.Age}");

Console.WriteLine();

// 2) Probe without throwing — TryGetTypeInfo returns false when
//    the resolver cannot produce metadata for the requested type.
//    We use a source-gen context that only knows about Person.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = PersonOnlyContext.Default
};

bool found = limited.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? pi);
Console.WriteLine($"Person in limited context? {found} (info is null: {pi is null})");

bool found2 = limited.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? oi);
Console.WriteLine($"Order  in limited context? {found2} (info is null: {oi is null})");

// --- types ---------------------------------------------------------------

public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

[JsonSerializable(typeof(Person))]
public partial class PersonOnlyContext : JsonSerializerContext;

